parms.snippet:
vector cen = set(0,0,0);
float dist = distance(@P, cen);
float rad= chf("rad");

float d = dist / rad;

d = chramp("ramp", d);

f@scaleval = d;

int pts[] = primpoints(0, @primnum);
vector pos1 = point(0, "P", pts[0]);
vector pos2 = point(0, "P", pts[1]);
vector uv1 = uvsample(1, "uv", "P", pos1);
vector uv2 = uvsample(1, "uv", "P", pos2);

vector rpos1 = uvsample(2, "P", "uv", uv1);
vector rpos2 = uvsample(2, "P", "uv", uv2);
float dist = distance(rpos1, rpos2);

vector cuv = uvsample(1, "uv", "P", @P);
float scaleval = uvsample(2, "scaleval", "uv", cuv);
scaleval = scaleval * ch("max_scale");

float f = @Frame / float($FEND);
scaleval = lerp(1.0, scaleval, f);

f@restlength = dist * scaleval;

// This is necessary for scale value to work
// if not present scale value goes down for some reason
f@aa = scaleval;

vector cuv = uvsample(1, "uv", "P", @P);
float scaleval = uvsample(2, "scaleval", "uv", cuv);

float minstiff = 0.01;
float maxstiff = 10.0;

f@stiffness = exp(lerp(log(maxstiff), log(minstiff), scaleval));

int pts[] = primpoints(0, @primnum);

vector pos1 = point(0, "P", pts[0]);
vector pos2 = point(0, "P", pts[1]);

float dist = distance(pos1, pos2);

float scaleval = prim(2, "scaleval", @primnum);
scaleval *= ch("max_scale");

float f = @Frame / float($FEND);
scaleval = lerp(1.0, scaleval, f);

f@scaleval = scaleval;

f@restlength = dist * scaleval;

// This is necessary for scale value to work
// if not present scale value goes down for some reason
f@aa = scaleval;

