import toolutils

node = hou.node(".")
sopsolver = hou.node("..")

# Attempt to discover a constraint network that we're wired to.
nodetypes = ["constraintnetwork"]
for nodetype in nodetypes:
    network = toolutils.findOutputNodeOfBaseType(sopsolver, nodetype)
    if network:
        return node.relativePathTo(network)

return "../.."

